def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Fill the two concave pockets of the continuous 5-stroke. The 7 pocket
    # is the small upper-left rectangle; the 8 pocket is the large lower/right
    # rectangle. Their boundaries are the stair-stepped arms of the stroke.
    # Detect 2x2 zero blocks with 5 rails on either side as the small pocket.
    for r in range(h - 1):
        for c in range(1, w - 3):
            if all(grid[y][x] == 0 for y in (r, r+1) for x in (c, c+1)):
                if all(grid[y][c-1] == 5 and grid[y][c+2] == 5 for y in (r, r+1)):
                    for y in (r, r+1):
                        for x in (c, c+1): out[y][x] = 7

    # Fill lower/right pocket cells in rows/columns beyond the 5 stroke's
    # inward-turning boundary; retain every original 5 and all open exterior.
    # A zero belongs to this pocket if bounded on two sides by the stroke.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or out[r][c] == 7:
                continue
            left = c > 0 and grid[r][c-1] == 5
            up = r > 0 and grid[r-1][c] == 5
            if left and up:
                out[r][c] = 8
    return out
