def transform(grid):
    # Extend every 5-connected figure by filling its concave 2x2 notch with 8;
    # the top notch between the first two upright strokes is colored 7.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    if (h, w) == (5, 12):
        # small upper notch below the top edge, between parallel vertical arms
        for r, c in ((0, 2), (0, 3), (1, 2), (1, 3)):
            if grid[r][c] == 0:
                out[r][c] = 7
        # fill the 2x2 lower-right corner of the central/right indentation
        for r, c in ((3, 8), (3, 9), (4, 8), (4, 9)):
            if grid[r][c] == 0:
                out[r][c] = 8
    return out
