    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0 or (r,c) in seen: continue
            st=[(r,c)];seen.add((r,c));co=[]
            while st:
                y,x=st.pop();co.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        yy,xx=y+dy,x+dx
                        if (dy or dx) and 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and (yy,xx) not in seen:
                            seen.add((yy,xx));st.append((yy,xx))
            comps.append(co)
    # Candidate cavities exclude the outermost-background region by 4-connectivity.
    seen=set(); enclosed=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=0 or (r,c) in seen: continue
       st=[(r,c)];seen.add((r,c));co=[];edge=False
       while st:
        y,x=st.pop();co.append((y,x));edge |= y==0 or y==h-1 or x==0 or x==w-1
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         yy,xx=y+dy,x+dx
         if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and (yy,xx) not in seen:seen.add((yy,xx));st.append((yy,xx))
       if not edge: enclosed.append(co)
    if enclosed:
      for y,x in max(enclosed,key=len): out[y][x]=8
    return out
